(function() {
  $("form.newsletter").on("submit", function(e) {
    var data, email;
    e.preventDefault();
    ga("send", "event", "Newsletter", "SubmitForm");
    email = $(".email", e.target).val();
    if (email === "") {
      alert(NewsLang.pleaseFillTheForm);
      return;
    }
    $(".submit").hide();
    $(".loading").removeClass("hidden");
    data = {
      email: email,
      lang: NewsLang.lang
    };
    return $.post("https://api.openwindmap.org/v1/shop/newsletter", data, (function(response, textStatus) {
      if (response.error) {
        alert(NewsLang.errorRetry);
        return ga("send", "event", "Newsletter", "ErrorForm");
      } else {
        alert(NewsLang.successNewsletter + email);
        $(".email").val("");
        return ga("send", "event", "Newsletter", "Subscribe");
      }
    }), "json").error(function() {
      alert(NewsLang.errorRetry);
      return ga("send", "event", "Newsletter", "ErrorForm");
    }).always(function() {
      $(".submit").show();
      return $(".loading").addClass("hidden");
    });
  });

}).call(this);

